BEGIN;
CREATE TABLE IF NOT EXISTS revenue.charge_policy(policy_id uuid PRIMARY KEY,category_code text NOT NULL,responsibility text NOT NULL CHECK(responsibility IN('POOL','MUDARIB','OTHER')),effective_from date NOT NULL,effective_to date,sharia_approval_id text REFERENCES workflow.approval_action(idempotency_key),version integer NOT NULL CHECK(version>0),created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK(effective_to IS NULL OR effective_to>=effective_from),UNIQUE(category_code,version));
CREATE TABLE IF NOT EXISTS revenue.pool_charge(charge_id uuid PRIMARY KEY,pool_id text NOT NULL REFERENCES pooling.pool(pool_id),category_code text NOT NULL,business_date date NOT NULL,currency_code text NOT NULL CHECK(currency_code~'^[A-Z]{3}$'),amount numeric(30,12) NOT NULL CHECK(amount>0),source_reference text NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE OR REPLACE FUNCTION revenue.reject_charge_history_mutation()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'Charge policies and imported charges are append-only';END;$$;DROP TRIGGER IF EXISTS charge_policy_immutable ON revenue.charge_policy;CREATE TRIGGER charge_policy_immutable BEFORE UPDATE OR DELETE ON revenue.charge_policy FOR EACH ROW EXECUTE FUNCTION revenue.reject_charge_history_mutation();DROP TRIGGER IF EXISTS pool_charge_immutable ON revenue.pool_charge;CREATE TRIGGER pool_charge_immutable BEFORE UPDATE OR DELETE ON revenue.pool_charge FOR EACH ROW EXECUTE FUNCTION revenue.reject_charge_history_mutation();
COMMIT;
